import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";
import { playwright } from "@vitest/browser-playwright";

const uuidBrowser = fileURLToPath(new URL("./node_modules/uuid/dist/index.js", import.meta.url));
const lib0Webcrypto = fileURLToPath(new URL("./node_modules/lib0/webcrypto.js", import.meta.url));

// Browser-mode config for specs that need real DOM/SVG geometry
// (getScreenCTM, getBoundingClientRect, pointer-event hit testing).
// jsdom's polyfill in src/jsdom-svg-polyfill.ts returns identity stubs,
// which is enough to instantiate jointjs but not to compute layout that
// click/hit tests depend on. See #4866.
export default defineConfig({
  // Vite's default resolution picks node entries for transitive deps
  // because @angular/build:unit-test sets a server-like environment.
  // Force the browser entry for the two offenders pulled in by
  // workflow-graph services (uuid + lib0/webcrypto via yjs).
  resolve: {
    conditions: ["browser", "module", "import", "default"],
    alias: [
      { find: /^uuid$/, replacement: uuidBrowser },
      { find: /^lib0\/webcrypto$/, replacement: lib0Webcrypto },
    ],
  },
  // `buffer` is imported only by the test setup file (src/browser-buffer-
  // polyfill.ts), which Vite's import-scan via the @angular/build:unit-test
  // builder does NOT crawl — without this hint the dep is served raw and
  // `require()` calls inside the CJS package crash on first import.
  // Explicit-include forces esbuild to pre-bundle it (alongside its
  // `base64-js` + `ieee754` transitive deps) into a browser-runnable ESM.
  optimizeDeps: {
    include: ["buffer"],
  },
  test: {
    // Emit a JUnit-XML report alongside the default console reporter so
    // Codecov Test Analytics can ingest browser-mode failures and detect
    // flakies on main. Written to a distinct filename so the upload step
    // can disambiguate it from the unit-test report.
    reporters: ["default", ["junit", { outputFile: "junit-browser.xml" }]],
    globals: true,
    // browser-buffer-polyfill must run FIRST: it puts Buffer/process on
    // globalThis before any test module loads, which is required for
    // monaco-editor-wrapper's eager Buffer.allocUnsafe references (under
    // jsdom-mode Vitest these are satisfied by Node's built-in Buffer; in
    // browser-mode the runtime has neither, so we install the `buffer` npm
    // package as a shim).
    setupFiles: ["src/browser-buffer-polyfill.ts", "src/test-zone-setup.ts"],
    // Browser mode resolves larger defaults than jsdom off `browser.enabled`
    // (15s per test, 30s per hook), but since #7717 raised the jsdom config to
    // 20s per test, 15s is the tightest per-test ceiling left in the frontend
    // job — on the slower of the two runtimes, since driving a real Chromium
    // through playwright costs more than jsdom. Both legs run on the same
    // macOS runners, whose stalls are what the jsdom raise was for, so this
    // one gets at least as much headroom. `hookTimeout` is left alone — its
    // browser-mode default is already the 30s the jsdom config sets. See
    // apache/texera#6073.
    testTimeout: 30_000,
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      instances: [{ browser: "chromium" }],
    },
    server: {
      deps: {
        inline: [/monaco-breakpoints/, /^uuid$/, /^lib0\//],
      },
    },
  },
});

